import griffe
from griffe.extensions import Extensions
from griffe.docstrings import Docstring

class AppendCheckedExtension(Extensions):
    def on_visit_function(self, function):
        if function.docstring:
            function.docstring.value += " [checked]"
        else:
            function.docstring = Docstring(" [checked]")

package = griffe.load("mypkg", extensions=[AppendCheckedExtension()])

for name, member in package.members.items():
    if member.is_function:
        docstring_text = member.docstring.value if member.docstring else "No docstring"
        print(f"{name}: {docstring_text}")
